#include <cstdio>
#include <algorithm>

using namespace std;

const int N = 2e5 + 5;
const int C = 1e6 + 5;

int n;
int a[N];
int vis[C];

void bubble_sort(int *a, int n) {
    bool flag = true;
    while (flag) {
        flag = false;
        for (int i = 1; i < n; ++i) {
            if (a[i] > a[i + 1]) {
                flag = true;
                int t = a[i];
                a[i] = a[i + 1];
                  a[i + 1] = t;
              }
          }
     }
}

int main() {
    scanf("%d", &n);
    a[1] = 1;
    vis[1] = 1;
     for (int i = 2; i <= n; i++) {
          if (a[i - 1] - i <= 0 || vis[a[i - 1] - i])
               a[i] = a[i - 1] + i;
          else
               a[i] = a[i - 1] - i;
          vis[a[i]] = 1;
      }
      bubble_sort(a, n);
      for (int i = 1; i <= n; i++)
          printf("%d%c", a[i], " \n"[i == n]);
      return 0;
}

