using namespace std;

static string expectedRecaman(int n) {
    vector<int> a(n + 1);
    set<int> vis;
    a[1] = 1;
    vis.insert(1);
    for (int i = 2; i <= n; ++i) {
        int cand = a[i - 1] - i;
        if (cand > 0 && vis.find(cand) == vis.end()) a[i] = cand;
        else a[i] = a[i - 1] + i;
        vis.insert(a[i]);
    }
    vector<int> v(a.begin() + 1, a.begin() + 1 + n);
    sort(v.begin(), v.end());
    ostringstream os;
    for (int i = 0; i < n; ++i) os << v[i] << (i + 1 == n ? '\n' : ' ');
    return os.str();
}
static bool parseEq(const string& a, const string& b) {
    vector<int> va, vb;
    istringstream isa(a), isb(b);
    int x;
    while (isa >> x) va.push_back(x);
    while (isb >> x) vb.push_back(x);
    return va == vb;
}
static bool check(const string& exe, int n, int id) {
    const string inF = "l4a12p1_in.txt", outF = "l4a12p1_out.txt";
    {
        ofstream o(inF);
        o << n << '\n';
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream in(outF);
    string got((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    if (code != 0 || !parseEq(got, expectedRecaman(n))) {
        cout << "[FAIL] case " << id << " (n=" << n << "): status=" << code
             << ", actual=" << got.substr(0, 200) << '\n';
        return false;
    }
    return true;
