#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

static vector<int> expectedAnswers(const vector<vector<string>>& cases) {
    vector<int> ans;
    for (size_t t = 0; t < cases.size(); ++t) {
        vector<string> v = cases[t];
        sort(v.begin(), v.end());
        string all;
        for (size_t i = 0; i < v.size(); ++i) all += v[i];
        int ok = 1;
        for (size_t i = 1; i < all.size(); ++i)
            if (all[i] < all[i - 1]) { ok = 0; break; }
        ans.push_back(ok);
    }
    return ans;
}
static bool check(const string& exe, const vector<vector<string>>& cases, int id) {
    const string inF = "l4a12p2_in.txt", outF = "l4a12p2_out.txt";
    {
        ofstream o(inF);
        o << cases.size() << '\n';
        for (size_t t = 0; t < cases.size(); ++t) {
            o << cases[t].size() << '\n';
            for (size_t i = 0; i < cases[t].size(); ++i) o << cases[t][i] << '\n';
        }
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream in(outF);
    vector<int> got;
    int x;
    while (in >> x) got.push_back(x);
    vector<int> want = expectedAnswers(cases);
    if (code != 0 || got != want) {
        cout << "[FAIL] case " << id << ": expected ";
        for (int v : want) cout << v << ' ';
        cout << ", actual ";
        for (int v : got) cout << v << ' ';
        cout << ", status=" << code << '\n';
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    vector<vector<string>> c1 = {
        vector<string>{"aa", "ac", "de"},
        vector<string>{"aac", "bc"},
        vector<string>{"gesp"}
    };
    ++total; if (check(exe, c1, 1)) ++passed;  // 样例
    vector<vector<string>> c2 = {
        vector<string>{"b", "a"},
        vector<string>{"ac", "b"},
        vector<string>{"a"},
        vector<string>{"ba"},
        vector<string>{"ab", "ba"},
        vector<string>{"a", "a"},
        vector<string>{"b", "a", "a"},
        vector<string>{"a", "b", "a"},
        vector<string>{"abc", "abcd"}
    };
    ++total; if (check(exe, c2, 2)) ++passed;  // 边界
    srand(20241201);
    for (int t = 0; t < 8; ++t) {
        int n = 1 + rand() % 5;
        vector<string> c;
        for (int i = 0; i < n; ++i) {
            int L = 1 + rand() % 4;
            string s;
            for (int k = 0; k < L; ++k) s += char('a' + rand() % 4);
            c.push_back(s);
        }
        ++total; if (check(exe, {c}, 3 + t)) ++passed;
    }
    for (int t = 0; t < 3; ++t) {
        int n = 1 + rand() % 100;
        vector<string> c;
        for (int i = 0; i < n; ++i) {
            int L = 1 + rand() % 10;
            string s;
            for (int k = 0; k < L; ++k) s += char('a' + rand() % 26);
            c.push_back(s);
        }
        ++total; if (check(exe, {c}, 11 + t)) ++passed;
    }
    cout << "Results: " << passed << "/" << total << " passed" << '\n';
    return passed == total ? 0 : 1;
}
